// 📁 src/app/app-routing.module.ts
// 🚀 ROUTING MIGRADO: Multi-Propiedades → Establecimiento Único + 5 Habitaciones

import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';

const routes: Routes = [
  {
    path: '',
    redirectTo: '/home',
    pathMatch: 'full'
  },
  {
    path: 'home',
    loadChildren: () => import('./pages/home/home.module').then(m => m.HomeModule)
  },
  
  // ✅ NUEVA RUTA: Room Selection (antes search-results)
  {
    path: 'rooms',
    loadChildren: () => import('./pages/search-results/search-results.module').then(m => m.SearchResultsModule),
    data: { 
      title: 'Nuestras Habitaciones',
      description: 'Habitaciones disponibles en nuestro establecimiento' 
    }
  },
  
  // ✅ NUEVA RUTA: Room Details (antes property/:id)
  {
    path: 'rooms/:roomId', 
    loadChildren: () => import('./pages/property-details/property-details.module').then(m => m.PropertyDetailsModule),
    data: { 
      title: 'Detalles de Habitación',
      description: 'Información completa de la habitación' 
    }
  },

  // ✅ ACTUALIZADA: Booking con roomId
  {
    path: 'booking/:roomId',
    loadChildren: () => import('./pages/booking/booking.module').then(m => m.BookingModule),
    data: { 
      title: 'Reservar Habitación',
      description: 'Reserva tu habitación paso a paso' 
    }
  },
  
  // ✅ MANTENER: Booking confirmation (sin cambios)
  {
    path: 'booking-confirmation/:bookingId',
    loadChildren: () => import('./pages/booking/booking.module').then(m => m.BookingModule),
    data: { 
      title: 'Reserva Confirmada',
      description: 'Confirmación de tu reserva' 
    }
  },

  // ================================
  // 🔄 REDIRECTS DE COMPATIBILIDAD
  // ================================
  
  // Redirect de la ruta antigua de search
  {
    path: 'search-results',
    redirectTo: '/rooms'
  },
  
  // Redirect de rutas antiguas de propiedades
  {
    path: 'property/:id',
    redirectTo: '/rooms/:id'
  },
  
  // Redirect de booking sin roomId (redirige a rooms)
  {
    path: 'booking',
    redirectTo: '/rooms'
  },
  
  // Redirects adicionales para mantener compatibilidad
  {
    path: 'search',
    redirectTo: '/rooms'
  },
  {
    path: 'reserve/:id',
    redirectTo: '/booking/:id'
  },
  {
    path: 'book/:id',
    redirectTo: '/booking/:id'
  },
  {
    path: 'habitaciones',
    redirectTo: '/rooms'
  },
  {
    path: 'habitacion/:id',
    redirectTo: '/rooms/:id'
  },
  
  // ✅ MANTENER: Wildcard redirect
  {
    path: '**',
    redirectTo: '/home'
  }
];

@NgModule({
  imports: [RouterModule.forRoot(routes, {
    enableTracing: false,
    scrollPositionRestoration: 'top',
    anchorScrolling: 'enabled',
    onSameUrlNavigation: 'reload'
  })],
  exports: [RouterModule]
})
export class AppRoutingModule { }
